<?php
require_once 'db.php';function esc($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
$allowed=['Pending','Preparing','Ready','Completed','Cancelled'];$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['order_id'],$_POST['status'])){$id=(int)$_POST['order_id'];$status=$_POST['status'];if(in_array($status,$allowed,true)){$st=$conn->prepare("UPDATE orders SET order_status=? WHERE order_id=?");$st->bind_param('si',$status,$id);$st->execute();$st->close();$st=$conn->prepare("INSERT INTO order_status_history(order_id,status) VALUES(?,?)");$st->bind_param('is',$id,$status);$st->execute();$st->close();$notice='Order status updated.';}}
$orders=$conn->query("SELECT o.order_id,o.order_number,o.order_date,o.total_amount,o.payment_method,o.payment_status,o.order_status, GROUP_CONCAT(CONCAT(p.product_name,' × ',oi.quantity,' (',COALESCE(oi.customization,'Regular'),')') SEPARATOR ', ') items FROM orders o LEFT JOIN order_items oi ON oi.order_id=o.order_id LEFT JOIN products p ON p.product_id=oi.product_id GROUP BY o.order_id ORDER BY o.order_date DESC LIMIT 100");
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff | Brew Eua's</title><link rel="stylesheet" href="kiosk.css"></head><body><header class="top"><a class="brand" href="index.php"><img src="logo.jpg" alt="Logo"><span>Brew Eua's<small>BREW & BITES</small></span></a><nav class="nav"><a href="index.php">Home</a><a href="menu.php">Menu</a><a href="order.php">Checkout</a><a class="active" href="staff.php">Staff orders</a><a href="admin.php">Admin</a></nav></header><main class="wrap"><h1 class="section-title">Staff order dashboard</h1><p class="muted">Demo staff screen. Protect this page with authentication before using it in a public or production environment.</p><?php if($notice): ?><div class="success"><?= esc($notice) ?></div><?php endif ?><div class="panel table-wrap"><table><thead><tr><th>Order</th><th>Date</th><th>Items</th><th>Total</th><th>Payment</th><th>Status</th><th>Update</th></tr></thead><tbody><?php if($orders) while($o=$orders->fetch_assoc()): ?><tr><td><strong>#<?= (int)$o['order_number'] ?></strong></td><td><?= esc($o['order_date']) ?></td><td><?= esc($o['items']??'') ?></td><td>₱<?= number_format((float)$o['total_amount'],2) ?></td><td><?= esc($o['payment_method']) ?><br><span class="status"><?= esc($o['payment_status']) ?></span></td><td><span class="status"><?= esc($o['order_status']) ?></span></td><td><form method="post" class="row"><input type="hidden" name="order_id" value="<?= (int)$o['order_id'] ?>"><select name="status"><?php foreach($allowed as $s): ?><option <?= $s===$o['order_status']?'selected':'' ?>><?= esc($s) ?></option><?php endforeach ?></select><button class="btn" type="submit">Save</button></form></td></tr><?php endwhile ?></tbody></table></div></main></body></html>